function Avatar({ initials, color='sage', size='md', verified=false }) { return <span className={`avatar avatar-${color} avatar-${size}`} aria-label={initials}>{initials}{verified && <span className="avatar-verified"><Icon name="check" size={9}/></span>}</span>; }
function Badge({ children, tone='neutral', dot=false }) { return <span className={`badge badge-${tone}`}>{dot && <i/>}{children}</span>; }
function Button({ children, icon, variant='primary', size='md', onClick, type='button', disabled=false, className='' }) { return <button type={type} disabled={disabled} className={`btn btn-${variant} btn-${size} ${className}`} onClick={onClick}>{icon && <Icon name={icon} size={size==='sm'?15:17}/>}<span>{children}</span></button>; }
function Toggle({ checked, onChange, label }) { return <button type="button" role="switch" aria-checked={checked} aria-label={label} className={`toggle ${checked?'is-on':''}`} onClick={()=>onChange(!checked)}><span/></button>; }

